#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using DeliveryService.Yun.Streetlights;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class DistrictDecor {
static Scene scene;static int count;static List<Light> lights;static List<GameObject> glows;
static DistrictDecor(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-district-decor"))return;File.Delete("Temp/Mok-district-decor");try{Build();}catch(Exception e){File.WriteAllText("Temp/Mok-district-decor.txt",e.ToString());Debug.LogException(e);}}
static GameObject Place(Transform parent,string name,Vector3 p,float yaw=0,float maxWidth=0){var asset=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonCity/Prefabs/"+name+".prefab");if(asset==null)throw new Exception(name);var g=(GameObject)PrefabUtility.InstantiatePrefab(asset,scene);g.transform.SetParent(parent,false);g.transform.SetPositionAndRotation(Vector3.zero,Quaternion.Euler(0,yaw,0));var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);if(maxWidth>0){float scale=Mathf.Min(1,maxWidth/Mathf.Max(b.size.x,b.size.z));g.transform.localScale*=scale;b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);}g.transform.position=p-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var c in g.GetComponentsInChildren<Collider>()){c.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(c);}PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);count++;return g;}
static void Lamp(Transform parent,Vector3 p,float yaw,bool small){var g=Place(parent,"Props/SM_Prop_LightPole_Base_0"+(small?2:1),p,yaw);AddLighting(g,small);}
static void AddLighting(GameObject g,bool small){if(g.GetComponentsInChildren<Light>(true).Length>0)return;var glow=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Yun/Streetlights/Visuals/StreetlightGlow.mat");foreach(float x in small?new[]{-.35f,.35f}:new[]{0f}){var obj=new GameObject("Mok district lamp");obj.transform.SetParent(g.transform,false);obj.transform.localPosition=small?new Vector3(x,4.63f,0):new Vector3(0,6.18f,1.96f);obj.transform.localRotation=Quaternion.Euler(90,0,0);var l=obj.AddComponent<Light>();l.type=small?LightType.Point:LightType.Spot;l.color=new Color(1,.79f,.52f);l.intensity=small?12:65;l.range=small?9:13;l.spotAngle=105;l.innerSpotAngle=65;l.shadows=LightShadows.None;l.cullingMask=~(1<<20);lights.Add(l);GameObject lens;if(small){lens=new GameObject("Mok lantern glow",typeof(MeshFilter),typeof(MeshRenderer));lens.GetComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scripts/Yun/Streetlights/Visuals/LanternGlow.asset");}else{lens=GameObject.CreatePrimitive(PrimitiveType.Cube);UnityEngine.Object.DestroyImmediate(lens.GetComponent<Collider>());lens.name="Mok lamp glow";}lens.transform.SetParent(g.transform,false);lens.transform.localPosition=small?new Vector3(x,4.635f,0):new Vector3(0,6.222f,1.96f);if(!small)lens.transform.localScale=new Vector3(.16f,.014f,.5f);var r=lens.GetComponent<MeshRenderer>();r.sharedMaterial=glow;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;r.receiveShadows=false;glows.Add(lens);}}
static void Build(){var old=SceneManager.GetActiveScene();string stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss");for(int i=0;i<SceneManager.sceneCount;i++)if(!EditorSceneManager.SaveScene(SceneManager.GetSceneAt(i),"Temp/Before-decor-"+stamp+"-"+i+".unity",true))throw new Exception("Scene backup failed");scene=SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);SceneManager.SetActiveScene(scene);if(!EditorSceneManager.SaveScene(scene,"Temp/JJinCity-before-decor-"+stamp+".unity",true))throw new Exception("Scene backup failed");var east=scene.GetRootGameObjects().First(g=>g.name=="Mok East City");var west=scene.GetRootGameObjects().First(g=>g.name=="Mok West Quarter");if(east.transform.Find("Street furniture")!=null)throw new Exception("Already decorated; preserve edits");lights=new List<Light>();glows=new List<GameObject>();count=0;var e=new GameObject("Street furniture").transform;e.SetParent(east.transform,false);var w=new GameObject("Alley furniture").transform;w.SetParent(west.transform,false);
foreach(float x in new[]{210f,290f,370f,440f})foreach(float z in new[]{-83f,-48f,27f,72f})foreach(int side in new[]{-1,1}){Lamp(e,new Vector3(x+side*8,.05f,z),side<0?90:270,false);Place(e,"Props/SM_Prop_Planter_01",new Vector3(x+side*8,.05f,z+7),0,2);Place(e,"Environments/SM_Env_Tree_0"+(z<0?1:2),new Vector3(x+side*8,.6f,z+7),0,3.2f);if(side>0){Place(e,"Props/SM_Prop_ParkBench_01",new Vector3(x+side*8,.05f,z-5),90,2.6f);Place(e,"Props/SM_Prop_TrashCan_01",new Vector3(x+side*8,.05f,z-8),0,1);}else{Place(e,"Props/SM_Prop_Mailbox_01",new Vector3(x+side*8,.05f,z-5),270,1.2f);Place(e,"Props/SM_Prop_Hydrant_01",new Vector3(x+side*8,.05f,z-8),0,1);}}
// 기존 확장 가로등에도 아직 조명이 없다면 같은 시간 제어를 연결한다.
foreach(var t in east.GetComponentsInChildren<Transform>().Where(t=>t.name=="East street lamp").ToArray())AddLighting(t.gameObject,false);
foreach(float x in new[]{-199f,-228f,-266f,-304f,-347f})foreach(int side in new[]{-1,1}){Lamp(w,new Vector3(x,.04f,-5+side*4.2f),0,true);Place(w,"Props/SM_Prop_TrashCan_01",new Vector3(x+1.3f,.04f,-5+side*6),0,.8f);Place(w,"Props/SM_Prop_TrashBag_02",new Vector3(x+2,.04f,-5+side*6.5f),25,.9f);}
foreach(float x in new[]{-218.5f,-256.5f,-294.5f,-332.5f})foreach(float z in new[]{-72f,-52f,22f,62f}){Place(w,"Props/SM_Prop_Pallet_01",new Vector3(x,.04f,z),90,1.5f);Place(w,"Props/SM_Prop_CardboardBox_03",new Vector3(x,.25f,z),10,1);Place(w,"Props/SM_Prop_PowerBox_01",new Vector3(x+.5f,.04f,z+2),90,1);}
Lamp(w,new Vector3(-176,.04f,8),180,false);Lamp(w,new Vector3(-176,.04f,-18),0,false);
var clock=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<DayNightCycle>(true)).First();var controller=new GameObject("Mok District Streetlights").AddComponent<StreetlightTimeController>();controller.Configure(clock,lights.ToArray(),glows.ToArray());
// 시간과 영업 상태를 복원하면서 기존 점등 규칙을 확인한다.
float time=clock.currentTime;bool open=clock.isShopOpen;clock.isShopOpen=true;clock.currentTime=12;controller.Refresh();if(lights.Any(l=>l.enabled))throw new Exception("Daylight switch failed");clock.currentTime=20;controller.Refresh();if(lights.Any(l=>!l.enabled))throw new Exception("Night switch failed");clock.currentTime=time;clock.isShopOpen=open;controller.Refresh();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();SceneManager.SetActiveScene(old);if(opened)EditorSceneManager.CloseScene(scene,true);File.WriteAllText("Temp/Mok-district-decor.txt","Saved: "+count+" props; "+lights.Count+" controlled lights. Day/night switching passed.");}
}}
#endif
